'use strict';
function normalizeQuery(value){return String(value??'').trim().toLocaleLowerCase('ar');}
function search(values,query){const q=normalizeQuery(query);const out=[];for(let i=0;i<values.length;i++){if(!q||String(values[i]??'').toLocaleLowerCase('ar').includes(q))out.push(i);}return out;}
function feeLedger(agreements,payments,query,today){
 const paidById=new Map();for(const p of payments){const k=p.agreementId;paidById.set(k,(paidById.get(k)||0)+(Number(p.amount)||0));}
 const amountPaid=id=>paidById.get(id)||0,matched=[],q=normalizeQuery(query);
 agreements.forEach((a,i)=>{if(!q||[a.client,a.description,a.caseNumber].some(v=>String(v||'').toLocaleLowerCase('ar').includes(q)))matched.push(i);});
 const total=agreements.reduce((n,a)=>n+(Number(a.total)||0),0),paid=agreements.reduce((n,a)=>n+amountPaid(a.id),0);
 const due=agreements.reduce((n,a)=>n+(a.dueDate&&a.dueDate<today&&(Number(a.total)||0)-amountPaid(a.id)>0?1:0),0);
 return {matched,total,paid,remain:total-paid,due,paidEntries:Array.from(paidById.entries())};
}
function voiceNorm(value){return String(value??'').normalize('NFKC').replace(/[\u064B-\u065F\u0670]/g,'').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[ـ]/g,'').replace(/\s+/g,' ').trim().toLocaleLowerCase('ar');}
function voiceDigits(value){return String(value??'').replace(/[٠-٩]/g,d=>String('٠١٢٣٤٥٦٧٨٩'.indexOf(d))).replace(/[۰-۹]/g,d=>String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d)));}
function voiceDate(year,month,day){const d=new Date(year,month-1,day,12);if(d.getFullYear()!==year||d.getMonth()!==month-1||d.getDate()!==day)return '';return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;}
function voiceAddDays(iso,days){const [y,m,d]=iso.split('-').map(Number),dt=new Date(y,m-1,d+days,12);return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;}
const voiceMonths={'يناير':1,'كانون الثاني':1,'فبراير':2,'مارس':3,'ابريل':4,'أبريل':4,'مايو':5,'يونيو':6,'يونيه':6,'يوليو':7,'يوليه':7,'اغسطس':8,'أغسطس':8,'سبتمبر':9,'اكتوبر':10,'أكتوبر':10,'نوفمبر':11,'ديسمبر':12};
function parseVoiceHearingDate(raw,todayKey){const text=voiceDigits(raw);let m=text.match(/(?:جلسة|لجلسة|يوم)?\s*(\d{1,2})\s*[\/\-.]\s*(\d{1,2})(?:\s*[\/\-.]\s*(\d{4}))?/),day,month,year;if(m){day=+m[1];month=+m[2];year=m[3]?+m[3]:null;}if(!m){const names=Object.keys(voiceMonths).sort((a,b)=>b.length-a.length).join('|');m=text.match(new RegExp(`(?:جلسة|لجلسة|يوم)?\\s*(\\d{1,2})\\s*(${names})(?:\\s*(\\d{4}))?`,'i'));if(!m)return '';day=+m[1];month=voiceMonths[m[2]];year=m[3]?+m[3]:null;}if(!Number.isInteger(day)||day<1||day>31||!Number.isInteger(month)||month<1||month>12)return '';const ty=+todayKey.slice(0,4);if(!year){year=ty;const c=voiceDate(year,month,day);if(!c)return '';if(c<=todayKey)year++;}const result=voiceDate(year,month,day);return result&&result>todayKey?result:'';}
function parseVoicePurpose(raw){const text=voiceDigits(raw),m=text.match(/(?:ل|علشان|عشان)?\s*(تقديم|ايداع|إيداع|احضار|إحضار|تسليم|اعلان|إعلان|مراجعة|استخراج|استيفاء)\s+(.+?)(?=\s+(?:و?صرف|مبلغ|مصروف|انتقالات|تصوير|رسوم)|$)/);if(!m)return '';const verb=m[1].replace(/^إ/,'ا'),rest=String(m[2]||'').replace(/[،,.؛]+$/,'').trim();return rest?verb+' '+rest:verb;}
function parseVoiceExpense(raw){const text=voiceDigits(raw),m=text.match(/(?:صرف|مصاريف|مبلغ)?\s*(\d+(?:[.,]\d+)?)\s*(?:جنيه(?:اً|ا)?|ج\s*م|جنيه|ج)(?!\w)/i);if(!m)return null;const amount=Number(String(m[1]).replace(',','.'));if(!Number.isFinite(amount)||amount<=0||amount>1000000)return null;const n=voiceNorm(text);let category='مصروفات أخرى';if(n.includes('انتقالات')||n.includes('مواصلات'))category='انتقالات';else if(n.includes('تصوير'))category='تصوير';else if(n.includes('رسوم اعلان'))category='رسوم إعلان';else if(n.includes('رسوم محكمه'))category='رسوم محكمة';return {amount,category};}
function parseVoiceCommand(raw,caseRow,todayKey){const transcript=String(raw||'').trim();if(!transcript)return {error:'اكتب الأمر الصوتي أولًا.'};const nextDate=parseVoiceHearingDate(transcript,todayKey);if(!nextDate)return {error:'لم أتعرف على تاريخ جلسة مستقبلية واضح. قل مثلًا: جلسة 15 يناير أو 15/01/2027.'};const purpose=parseVoicePurpose(transcript);if(!purpose)return {error:'لم أتعرف على الإجراء المطلوب للمهمة. اذكره بوضوح مثل: لتقديم المستندات.'};const names=(Array.isArray(caseRow?.clients)&&caseRow.clients.length?caseRow.clients:[caseRow?.client]).filter(Boolean).map(x=>String(x).trim()).filter(Boolean);if(!names.length)return {error:'القضية لا تحتوي اسم موكل واضحًا؛ راجع ملف القضية أولًا.'};const explicit=transcript.match(/(?:قضية|موكل|الموكل)\s+([^،.]+?)(?=\s+(?:لجلسة|جلسة|يوم|بتاريخ|لتقديم|لإيداع|وصرف|صرف)|$)/);if(explicit){const spoken=voiceNorm(explicit[1]);const matches=names.some(n=>{const nn=voiceNorm(n);return spoken===nn||nn.split(' ').some(t=>t.length>2&&spoken.includes(t));});if(!matches)return {error:'اسم الموكل الذي ورد في الأمر لا يطابق القضية المفتوحة. اختر القضية الصحيحة أو صحح النص.'};}const expense=parseVoiceExpense(transcript);return {nextDate,purpose,taskDate:voiceAddDays(nextDate,-7),expense,clientNames:names,caseNumber:String(caseRow.number||''),court:String(caseRow.court||''),caseKey:String(caseRow.caseId||caseRow.id||''),decision:'تأجيل'};}

self.onmessage=function(event){const m=event.data||{};try{let result;if(m.op==='voiceParse')result=parseVoiceCommand(m.payload?.text,m.payload?.caseRow,m.payload?.today);else if(m.op==='search')result=search(m.payload?.values||[],m.payload?.query||'');else if(m.op==='feeLedger')result=feeLedger(m.payload?.agreements||[],m.payload?.payments||[],m.payload?.query||'',m.payload?.today||'');else throw new Error('Unsupported worker operation');self.postMessage({id:m.id,result});}catch(error){self.postMessage({id:m.id,error:String(error?.message||error)});}};
